class Solution {
public:
     class SegmentTreeAnd
{
    vector<int> arr, tree;
    int n;
    void segBuild(int node, int st, int en)
    {
        if (st > en)
            return;
        if (st == en)
        {
            tree[node] = arr[st];
            return;
        }
        int md = st + (en - st) / 2;
        segBuild(2 * node, st, md);
        segBuild(2 * node + 1, md + 1, en);
        tree[node] = tree[2 * node] & tree[2 * node + 1];
    }
    int segQuery(int node, int st, int en, int l, int r)
    {
        if (st > r || en < l)
            return -1;
        if (st >= l && en <= r)
            return tree[node];
        int md = st + (en - st) / 2;
        int s1 = segQuery(2 * node, st, md, l, r);
        int s2 = segQuery(2 * node + 1, md + 1, en, l, r);
        return s1 & s2;
    }

public:
    SegmentTreeAnd(vector<int> &temp)
    {
        arr = temp;
        n = arr.size();
        tree.resize(4 * n, -1);
        segBuild(1, 0, n - 1);
    }
    int query(int l, int r)
    {
        return segQuery(1, 0, n - 1, l, r);
    }
};


    long long countSubarrays(vector<int>& nums, int k) {
        SegmentTreeAnd obj(nums);
        long long ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            int st = i, en = n - 1;
            long long first = -1, last = -2;
            while (st <= en) {
                int md = st + (en - st) / 2;
                int val = obj.query(i, md); 
                if(val == k)
                {
                    first = md; 
                    en = md-1; 
                }
                else if(val > k)
                    st = md+1; 
                else 
                    en = md-1; 
            }
            st = i;
            en = n - 1;
            while (st <= en) {
                int md = st + (en - st) / 2;
                int val = obj.query(i, md); 
                if(val == k)
                {
                    last = md; 
                    st = md+1;  
                }
                else if(val > k)
                    st = md+1; 
                else 
                    en = md-1; 
            }
            // cout << first<<' '<<last<<endl; 
            if (first != -1 && last != -2) {
                ans += (last - first + 1);
            }
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long count = 0;
        unordered_map<long long, long long> previous;

        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> current;

            if (nums[i] == k) {
                count++;
            }

            current[nums[i]] = 1;

            for (const auto& it : previous) {
                long long andresult = it.first & nums[i];

                if (andresult == k) {
                    count += it.second;
                }

                current[andresult] += it.second;
            }

            previous = move(current);
        }

        return count;
    }
};

